//! Code generated by `topics!`: one module per level, holding `Topic`,
//! `TopicRef`, the `Steps` trait, the leaf types, the group enums and the child
//! modules, and a `prelude` in the root's module.
//!
//! Generated names (`TopicRef::Push`, `PushLeaf`, `PushQueue`, the `push` method
//! and module) carry the span of the topic name, so editors go to its
//! declaration.

use proc_macro2::{Span, TokenStream, TokenTree};
use quote::{format_ident, quote};
use syn::ext::IdentExt;
use syn::{AttrStyle, Attribute, Ident, LitInt, LitStr};

use crate::parse::{Delivery, Entry, GroupEnum, Input, Kind, segment_id};

/// Whether to implement `Wire<C>` for bridges: set by nattes's `bridge` feature.
const BRIDGE: bool = cfg!(feature = "bridge");

pub fn expand(input: &Input) -> TokenStream {
    let mut cx = Cx {
        krate: &input.krate,
        attrs: &input.attrs,
        prelude: Vec::new(),
    };
    cx.module(&input.root, &Delivery::default(), "", &[])
}

struct Cx<'a> {
    krate: &'a TokenTree,
    /// Applied to every `TopicRef` enum.
    attrs: &'a [Attribute],
    /// What the prelude re-exports.
    prelude: Vec<TokenStream>,
}

/// What a child adds to its parent's module.
#[derive(Default)]
struct Child {
    ref_variant: TokenStream,
    view_arm: TokenStream,
    wire_bounds: TokenStream,
    encode_arm: TokenStream,
    decode_arm: TokenStream,
    signature: TokenStream,
    method: TokenStream,
    item: TokenStream,
}

impl Cx<'_> {
    /// The module of the level `entry`, below a level with the delivery
    /// defaults `outer`, on `subject`, at `path` from the root's
    /// module (empty for the root itself).
    fn module(
        &mut self,
        entry: &Entry,
        outer: &Delivery,
        subject: &str,
        path: &[&Ident],
    ) -> TokenStream {
        let Kind::Level(children) = &entry.kind else {
            unreachable!("only levels have a module")
        };
        let k = self.krate;
        let (docs, name, attrs) = (&entry.docs, &entry.name, self.attrs);
        let delivery = entry.delivery.or(outer);
        let defaults = self.defaults(&delivery);
        let mut parts = Vec::new();
        for child in children {
            parts.push(self.child(child, &delivery, subject, path));
        }
        let ref_variants = parts.iter().map(|c| &c.ref_variant);
        let view_arms = parts.iter().map(|c| &c.view_arm);
        let wire_bounds = parts.iter().map(|c| &c.wire_bounds);
        let encode_arms = parts.iter().map(|c| &c.encode_arm);
        let decode_arms = parts.iter().map(|c| &c.decode_arm);
        let signatures = parts.iter().map(|c| &c.signature);
        let methods = parts.iter().map(|c| &c.method);
        let items = parts.iter().map(|c| &c.item);

        // declared with the span of the level's name, to go there from them
        let topic = Ident::new("Topic", name.span());
        let topic_ref = Ident::new("TopicRef", name.span());
        let steps = Ident::new("Steps", name.span());
        // `TopicRef` uses its lifetime in every variant; an empty level has none
        let never = children.is_empty().then(|| {
            quote! {
                #[doc(hidden)]
                __Never(::core::marker::PhantomData<&'a ()>, ::core::convert::Infallible)
            }
        });
        let level_path = path.iter().map(|ident| quote!(#ident::));
        self.prelude.push(quote! {
            #[allow(unused_imports)]
            pub use super::#(#level_path)* Steps as _;
        });
        let about = if subject.is_empty() {
            "the root".to_string()
        } else {
            format!("`{subject}`")
        };
        let topic_doc = format!("The level {about}: the `T` of its channels.");
        let ref_doc = format!("A message of {about}, as a subscriber there sees it with `Msg::view`: which child topic it was published on.");
        let steps_doc = format!("The steps down from {about}: one method per child topic.");
        let queue = Ident::new("Queue", name.span());
        let groups = entry
            .groups
            .as_ref()
            .map(|groups| self.group_enum(&queue, &topic, groups, &about));
        let wire = BRIDGE.then(|| {
            quote! {
                impl<C> #k::Wire<C> for Topic
                where
                    #(#wire_bounds)*
                {
                    #[allow(unused_variables)]
                    fn encode(
                        below: &[#k::Seg],
                        payload: &dyn ::core::any::Any,
                        codec: &C,
                        out: &mut ::std::vec::Vec<u8>,
                    ) -> ::core::result::Result<(), #k::CodecError> {
                        let (seg, rest) = below
                            .split_first()
                            .expect("events are published on leaves");
                        match seg.id() {
                            #(#encode_arms)*
                            _ => unreachable!("events are published on topics of the tree"),
                        }
                    }

                    #[allow(unused_variables, unused_mut)]
                    fn decode(
                        mut path: #k::Path,
                        ids: &[u32],
                        bytes: &mut &[u8],
                        codec: &C,
                    ) -> ::core::result::Result<#k::Event, #k::WireError> {
                        let ::core::option::Option::Some((id, rest)) = ids.split_first() else {
                            return ::core::result::Result::Err(#k::WireError::UnknownTopic);
                        };
                        match *id {
                            #(#decode_arms)*
                            _ => ::core::result::Result::Err(#k::WireError::UnknownTopic),
                        }
                    }
                }
            }
        });
        // the root's module holds the prelude, complete once its children are expanded
        let prelude = path.is_empty().then(|| {
            let prelude = &self.prelude;
            quote! {
                /// Brings the `Steps` trait of every level of this tree into scope,
                /// mounted trees included: `use topics::prelude::*;`.
                pub mod prelude {
                    #(#prelude)*
                }
            }
        });

        quote! {
            #(#docs)*
            pub mod #name {
                #[allow(unused_imports)]
                use super::*;

                #[doc = #topic_doc]
                pub enum #topic {}

                #(#attrs)*
                #[doc = #ref_doc]
                #[allow(clippy::enum_variant_names)]
                pub enum #topic_ref<'a> { #(#ref_variants,)* #never }

                #groups

                impl #k::Topic for Topic {
                    type View<'a> = TopicRef<'a>;

                    #defaults

                    #[allow(unused_variables)]
                    fn view<'a>(
                        below: &'a [#k::Seg],
                        payload: &'a dyn ::core::any::Any,
                    ) -> TopicRef<'a> {
                        let (seg, rest) = below
                            .split_first()
                            .expect("events are published on leaves");
                        match seg.id() {
                            #(#view_arms)*
                            _ => unreachable!("events are published on topics of the tree"),
                        }
                    }
                }

                impl #k::Level for Topic {}

                #wire

                #[doc = #steps_doc]
                // method names are topic names, so naming conventions don't apply
                #[allow(clippy::new_ret_no_self, clippy::wrong_self_convention, clippy::should_implement_trait)]
                pub trait #steps<P> {
                    #(#signatures)*
                }

                #[allow(clippy::new_ret_no_self, clippy::wrong_self_convention, clippy::should_implement_trait)]
                impl<P: 'static> Steps<P> for #k::Channel<Topic, P> {
                    #(#methods)*
                }

                #(#items)*

                #prelude
            }
        }
    }

    /// What `entry` adds to its parent, on `parent`, the level at `path` with
    /// the delivery defaults `outer`.
    fn child(&mut self, entry: &Entry, outer: &Delivery, parent: &str, path: &[&Ident]) -> Child {
        let k = self.krate;
        let name = &entry.name;
        let seg = name.unraw().to_string();
        let lit = LitStr::new(&seg, name.span());
        let id = LitInt::new(&format!("{}u32", segment_id(&seg)), Span::call_site());
        let info = quote!(&const { #k::SegInfo::new(#id, #lit) });
        let var = Ident::new(&camel(&seg), name.span());
        let mut subject = if parent.is_empty() {
            seg.clone()
        } else {
            format!("{parent}.{seg}")
        };
        if entry.param.is_some() {
            subject.push_str(".*");
        }
        let docs = &entry.docs;
        let gap = (!docs.is_empty()).then(|| quote!(#[doc = ""]));
        let about = format!("Subject `{subject}`.");
        let doc = quote!(#(#docs)* #gap #[doc = #about]);

        // the topic below the step: its type, its `TopicRef` part, and the view
        // of an event there
        let (target, ref_inner, view, item) = match &entry.kind {
            Kind::Level(_) => {
                let mut sub: Vec<&Ident> = path.to_vec();
                sub.push(name);
                (
                    quote!(#name::Topic),
                    quote!(#name::TopicRef<'a>),
                    quote!(<#name::Topic as #k::Topic>::view(rest, payload)),
                    self.module(entry, outer, &subject, &sub),
                )
            }
            Kind::Mount(module) => {
                // A relative path resolves in the module around `topics!`,
                // through the `use super::*` of every level: from the prelude,
                // that module is `super::super`
                let first = module.segments.first().map(|s| s.ident.to_string());
                let absolute = module.leading_colon.is_some()
                    || matches!(first.as_deref(), Some("crate" | "$crate"));
                let around = (!absolute).then(|| quote!(super::super::));
                self.prelude.push(quote! {
                    #[allow(unused_imports)]
                    pub use #around #module::prelude::*;
                });
                (
                    quote!(#module::Topic),
                    quote!(#module::TopicRef<'a>),
                    quote!(<#module::Topic as #k::Topic>::view(rest, payload)),
                    quote!(),
                )
            }
            Kind::Leaf { msg, reply } => {
                let leaf = format_ident!("{}Leaf", var);
                let leaf_doc = format!("The leaf type of `{subject}`: the `T` of its channels.");
                let defaults = self.defaults(&entry.delivery.or(outer));
                let groups = entry.groups.as_ref().map(|groups| {
                    let queue = format_ident!("{}Queue", var);
                    self.group_enum(&queue, &leaf, groups, &format!("`{subject}`"))
                });
                let ends = match reply {
                    None => quote!(impl #k::Publish for #leaf { type Msg = #msg; }),
                    Some(reply) => quote! {
                        impl #k::Request for #leaf {
                            type Reply = #reply;
                        }
                    },
                };
                let wire = BRIDGE.then(|| {
                    quote! {
                        impl<C: #k::Codec<#msg>> #k::Wire<C> for #leaf {
                            fn encode(
                                _: &[#k::Seg],
                                payload: &dyn ::core::any::Any,
                                codec: &C,
                                out: &mut ::std::vec::Vec<u8>,
                            ) -> ::core::result::Result<(), #k::CodecError> {
                                #k::__encode_leaf::<#msg, C>(payload, codec, out)
                            }

                            fn decode(
                                path: #k::Path,
                                ids: &[u32],
                                bytes: &mut &[u8],
                                codec: &C,
                            ) -> ::core::result::Result<#k::Event, #k::WireError> {
                                #k::__decode_leaf::<#msg, C>(path, ids, bytes, codec)
                            }
                        }
                    }
                });
                (
                    quote!(#leaf),
                    quote!(&'a #msg),
                    quote!(#k::__payload::<#msg>(payload)),
                    quote! {
                        #(#docs)*
                        #gap
                        #[doc = #leaf_doc]
                        pub enum #leaf {}

                        #groups

                        impl #k::Topic for #leaf {
                            type View<'a> = &'a #msg;

                            #defaults

                            fn view<'a>(
                                _: &'a [#k::Seg],
                                payload: &'a dyn ::core::any::Any,
                            ) -> &'a #msg {
                                #k::__payload(payload)
                            }
                        }

                        impl #k::Leaf for #leaf {
                            type Msg = #msg;
                        }

                        #ends

                        #wire
                    },
                )
            }
        };

        match &entry.param {
            None => Child {
                ref_variant: quote!(#doc #var(#ref_inner)),
                view_arm: quote!(#id => TopicRef::#var(#view),),
                wire_bounds: quote!(#target: #k::Wire<C>,),
                encode_arm: quote!(#id => <#target as #k::Wire<C>>::encode(rest, payload, codec, out),),
                decode_arm: quote! {
                    #id => {
                        path.push(#k::Seg::plain(#info));
                        <#target as #k::Wire<C>>::decode(path, rest, bytes, codec)
                    }
                },
                signature: quote! {
                    #doc
                    fn #name(&self) -> #k::Channel<#target, P>;
                },
                method: quote! {
                    fn #name(&self) -> #k::Channel<#target, P> {
                        self.__plain::<#target>(#info)
                    }
                },
                item,
            },
            Some(param) => Child {
                ref_variant: quote!(#doc #var(&'a #param, #ref_inner)),
                view_arm: quote!(#id => TopicRef::#var(#k::__param::<#param>(seg), #view),),
                wire_bounds: quote!(#target: #k::Wire<C>, C: #k::Codec<#param>,),
                encode_arm: quote! {
                    #id => {
                        #k::__encode_param::<#param, C>(codec, seg, out)?;
                        <#target as #k::Wire<C>>::encode(rest, payload, codec, out)
                    }
                },
                decode_arm: quote! {
                    #id => {
                        let value = #k::__decode_param::<#param, C>(codec, bytes)?;
                        path.push(#k::Seg::fixed(#info, value));
                        <#target as #k::Wire<C>>::decode(path, rest, bytes, codec)
                    }
                },
                signature: quote! {
                    #doc
                    fn #name<S: #k::Param<#param>>(&self, select: S) -> #k::Channel<#target, #k::Append<P, S::Q>>
                    where
                        P: #k::AppendParams<S::Q>;
                },
                method: quote! {
                    fn #name<S: #k::Param<#param>>(&self, select: S) -> #k::Channel<#target, #k::Append<P, S::Q>>
                    where
                        P: #k::AppendParams<S::Q>,
                    {
                        self.__param::<#target, #param, S>(#info, select)
                    }
                },
                item,
            },
        }
    }

    /// The consts of `Topic` for the delivery defaults set on a topic or
    /// above it; the trait's own defaults apply to the others.
    fn defaults(&self, delivery: &Delivery) -> TokenStream {
        let k = self.krate;
        let buffer = delivery
            .buffer
            .as_ref()
            .map(|size| quote!(const BUFFER: usize = #size;));
        let on_full = delivery
            .on_full
            .as_ref()
            .map(|overflow| quote!(const ON_FULL: #k::Overflow = #k::Overflow::#overflow;));
        quote!(#buffer #on_full)
    }

    /// The group enum `name` of the topic `about`, whose channels have the
    /// type `scope` (its `Topic` enum or leaf type).
    fn group_enum(&self, name: &Ident, scope: &Ident, groups: &GroupEnum, about: &str) -> TokenStream {
        let k = self.krate;
        let attrs = groups.attrs.iter().map(|attr| Attribute {
            style: AttrStyle::Outer,
            ..attr.clone()
        });
        let variants = groups.variants.iter();
        let doc = format!("Queue groups of {about}: joined with `queue` on its channels.");
        quote! {
            #[doc = #doc]
            #(#attrs)*
            #[derive(Clone, PartialEq, Eq, Hash)]
            pub enum #name { #(#variants),* }

            impl #k::QueueGroup for #name {}
            impl #k::InScope<#scope> for #name {}
        }
    }
}

/// `pull_request` is `PullRequest`.
fn camel(name: &str) -> String {
    name.split('_')
        .flat_map(|word| {
            let mut chars = word.chars();
            let first = chars.next().into_iter().flat_map(char::to_uppercase);
            first.chain(chars)
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::camel;

    #[test]
    fn camel_case() {
        assert_eq!(camel("push"), "Push");
        assert_eq!(camel("pull_request"), "PullRequest");
        assert_eq!(camel("a__b_"), "AB");
    }
}
